ENTI_FLAG, #{item.sendStatus,jdbcType=VARCHAR} SEND_STATUS, #{item.submitTime,jdbcType=TIMESTAMP} SUBMIT_TIME, #{item.submitFeedbackStatus,jdbcType=VARCHAR} SUBMIT_FEEDBACK_STATUS, #{item.sumitSeq,jdbcType=VARCHAR} SUMIT_SEQ, #{item.statusDate,jdbcType=TIMESTAMP} STATUS_DATE, #{item.isMarketFund,jdbcType=VARCHAR} IS_MARKET_FUND, #{item.pbcSubmitDeadline,jdbcType=TIMESTAMP} PBC_SUBMIT_DEADLINE, #{item.submitDeadline,jdbcType=TIMESTAMP} SUBMIT_DEADLINE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.datZipCode,jdbcType=VARCHAR} DAT_ZIP_CODE, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.updateTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.createTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.crossBorderFlag,jdbcType=VARCHAR} CROSS_BORDER_FLAG, #{item.zjxtFlag,jdbcType=VARCHAR} ZJXT_FLAG from dual
